          "lines": [
            {
              "html": "A phrase with a number is called a number phrase, e.g. 'six books'. There are two types of numbers: 1. Cardinal Number: shows how many things there are, e.g. one, two, three. 2. Ordinal Number: shows the position of something, e.g. first, second, third. A cardinal number phrase is comprised of a number, the عَدَدٌ, and the item being quantified, the مَعْدُوْدٌ ('six' = عَدَدٌ, 'books' = مَعْدُوْدٌ). There are six types of Arabic cardinal numbers according to their grammatical function: 1–2, 3–10, 11–19, Tens, Tens and Units, 100s and 1,000s.",
              "list": false
            }
          ],
